CREATE TABLE IF NOT EXISTS categories (slug TEXT PRIMARY KEY,parent_slug TEXT REFERENCES categories(slug),label TEXT NOT NULL,description TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS evidence (id TEXT PRIMARY KEY,category_slug TEXT NOT NULL REFERENCES categories(slug),title TEXT NOT NULL,url TEXT NOT NULL UNIQUE,published_at TEXT,kind TEXT NOT NULL,evidence_level TEXT NOT NULL CHECK(evidence_level IN ('independent_study','author_reported','experimental','verified_execution')),review_status TEXT NOT NULL CHECK(review_status IN ('curated','unreviewed')),result TEXT NOT NULL,limitations TEXT NOT NULL DEFAULT '',action TEXT NOT NULL DEFAULT '',ingested_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS evidence_category_date ON evidence(category_slug,published_at DESC);
CREATE INDEX IF NOT EXISTS evidence_review_date ON evidence(review_status,published_at DESC);
CREATE TABLE IF NOT EXISTS ingest_runs (id INTEGER PRIMARY KEY AUTOINCREMENT,started_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,source TEXT NOT NULL,imported INTEGER NOT NULL DEFAULT 0,outcome TEXT NOT NULL CHECK(outcome IN ('success','failure')),detail TEXT NOT NULL DEFAULT '');
